#!/usr/bin/env python3
"""cell/cellpose-segment — auto-generated run.py (archetype=omics_scrna).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "omics_scrna"
BRAIN = "cell"
SKILL = "cellpose-segment"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'mask_path': 'out/mask.tif', 'n_cells': 78, 'per_cell_features_csv': 'out/per_cell_features.csv', 'overlay_png': 'out/overlay.png', 'iou_vs_manual': 0.78, 'border_cells_filtered': 12, 'passed_sanity': True})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """Cellpose 2D segmentation。host_env=PRAXIS-Cell。
    输入:image_path / model_type (cyto/nuclei) / diameter / channels
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    img = payload.get("image_path") or payload.get("input_tif")
    model = payload.get("model_type", "cyto3")
    diameter = float(payload.get("diameter", 30))
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="cellpose_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "model": model, "diameter": diameter, "out_dir": out_dir}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL,
                "mask_path": "", "n_cells": 0, "per_cell_features_csv": "",
                "overlay_png": "", "iou_vs_manual": 0.0,
                "border_cells_filtered": 0, "passed_sanity": True,
                "diagnostics": {**diagnostics, "dry": True}}
    if not img or not _os.path.isfile(img):
        return {"ok": False, "error": "需要 image_path", "diagnostics": diagnostics}
    mask_path = _os.path.join(out_dir, "mask.tif")
    feats_csv = _os.path.join(out_dir, "per_cell_features.csv")
    script = (
        "import json, sys, os, csv, numpy as np, tifffile\n"
        "from cellpose import models\n"
        "from skimage.measure import regionprops_table\n"
        f"img_p = {img!r}; model_t = {model!r}; diam = {diameter}\n"
        f"mask_p = {mask_path!r}; feats_p = {feats_csv!r}\n"
        f"os.makedirs({out_dir!r}, exist_ok=True)\n"
        "img = tifffile.imread(img_p)\n"
        "if img.ndim == 3 and img.shape[0] <= 4: img = img[0]  # take ch0\n"
        "mdl = models.Cellpose(gpu=True, model_type=model_t)\n"
        "masks, flows, styles, diams = mdl.eval(img, diameter=diam, channels=[0,0])\n"
        "tifffile.imwrite(mask_p, masks.astype(np.uint16))\n"
        "tbl = regionprops_table(masks, properties=('label','area','eccentricity','solidity','centroid'))\n"
        "n = int(masks.max())\n"
        "with open(feats_p, 'w') as fh:\n"
        "    w = csv.writer(fh); w.writerow(list(tbl.keys()))\n"
        "    for i in range(n): w.writerow([tbl[k][i] for k in tbl])\n"
        "json.dump({'mask_path': mask_p, 'n_cells': n, 'per_cell_features_csv': feats_p,\n"
        "           'passed_sanity': n > 0}, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=int(payload.get("timeout_s", 600)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "cellpose 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL, **parsed,
            "overlay_png": "", "iou_vs_manual": 0.0, "border_cells_filtered": 0,
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
